// Compiles every tests/solidity/test/*.t.sol with the npm solc (0.8.24, evmVersion cancun), resolving imports against
// solidity/src (generated by the dump) and solidity/test. This catches the Solidity compile errors the Foundry suites
// would hit without needing forge, so `npm test` stays meaningful on a machine without Foundry. Part of npm test.
import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const require = createRequire(import.meta.url);
const solc = require('solc');
const here = path.dirname(fileURLToPath(import.meta.url));
const solidityDir = path.join(here, 'solidity');

let pass = 0, fail = 0;
const ok = (c, m) => { if (c) pass++; else { fail++; console.log('  FAIL  ' + m); } };

/* generate the sources the tests import (idempotent) */
for (const d of ['dump-portable-sources.mjs', 'dump-swap-sources.mjs']) {
  const r = spawnSync('node', [path.join(here, d)], { encoding: 'utf8', maxBuffer: 100 * 1024 * 1024 });
  if (r.status !== 0) ok(false, d + ' failed', (r.stderr || '').slice(0, 200));
}

/* resolve imports transitively, keyed by their path relative to solidity/ (so solc finds them) */
function resolve(fileAbs, into) {
  const key = path.relative(solidityDir, fileAbs).replace(/\\/g, '/');
  if (into.has(key)) return;
  const src = fs.readFileSync(fileAbs, 'utf8');
  into.set(key, src);
  for (const m of src.matchAll(/import\s+["']([^"']+)["']/g)) {
    const r = path.resolve(path.dirname(fileAbs), m[1]);
    if (fs.existsSync(r)) resolve(r, into);
  }
}

const tests = fs.readdirSync(path.join(solidityDir, 'test')).filter((x) => x.endsWith('.t.sol')).sort();
ok(tests.length >= 10, 'there are at least 10 Foundry test files', String(tests.length));
for (const f of tests) {
  const into = new Map();
  resolve(path.join(solidityDir, 'test', f), into);
  const input = {
    language: 'Solidity',
    sources: Object.fromEntries([...into].map(([k, v]) => [k, { content: v }])),
    settings: { evmVersion: 'cancun', outputSelection: { '*': { '*': ['abi'] } } },
  };
  const out = JSON.parse(solc.compile(JSON.stringify(input)));
  const errs = (out.errors || []).filter((e) => e.severity === 'error');
  if (errs.length) {
    for (const e of errs.slice(0, 6)) {
      fail++;
      console.log('  FAIL  ' + f + ': ' + e.formattedMessage.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 260));
    }
  } else {
    ok(true, f + ' compiles');
  }
}

console.log('\n' + pass + ' passed, ' + fail + ' failed');
process.exit(fail ? 1 : 0);
